candidates.raw:
    size_t i;
    double e_i;
    adcs_vec3_t axis;
    adcs_vec3_t term;
    adcs_status_t st;

    if ((momentum == NULL) || (momentum_norm == NULL) ||
        (energy_axis == NULL) || (energy == NULL))
        return ADCS_E_NULL;

    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *momentum_norm = 0.0;
    *energy_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    *energy = 0.0;

    if (wheels == NULL)
        return ADCS_E_NULL;
    if ((count < 1U) || (count > 16U))
        return ADCS_E_RANGE;

    for (i = 0; i < count; i++) {
        if ((!adcs_is_finite_vec3(&wheels[i].axis_body)) ||
            (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK))
            return ADCS_E_RANGE;
        if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0))
            return ADCS_E_RANGE;
        if (!isfinite(wheels[i].speed_rad_s))
            return ADCS_E_RANGE;

        e_i = 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;
        *energy += e_i;

        term.x = e_i * axis.x;
        term.y = e_i * axis.y;
        term.z = e_i * axis.z;
        *energy_axis = adcs_vec3_add(energy_axis, &term);
    }

    st = adcs_wheel_momentum(wheels, count, momentum);
    if (st != ADCS_OK) {
        *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
        *momentum_norm = 0.0;
        *energy_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
        *energy = 0.0;
        return st;
    }

    *momentum_norm = adcs_vec3_norm(momentum);
    return ADCS_OK;
}

